export type ParsedHarvestDividendInstruction<
  TProgram extends string = typeof LEDGERLINE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    config: TAccountMetas[0];
    line: TAccountMetas[1];
    asset: TAccountMetas[2];
    /** is the Token-2022 program and that the ScaledUiAmount extension is present. */
    mint: TAccountMetas[3];
    vault: TAccountMetas[4];
    /** Protocol-owned destination for the trimmed tokens, pending conversion. */
    treasury: TAccountMetas[5];
    /**
     * Seeded with `effective_ts`, so one corporate action can only ever
     * produce one event. This is the idempotency guarantee.
     */
    dividendEvent: TAccountMetas[6];
    keeper: TAccountMetas[7];
    tokenProgram: TAccountMetas[8];
    systemProgram: TAccountMetas[9];
  };
  data: HarvestDividendInstructionData;
};

export function parseHarvestDividendInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedHarvestDividendInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      config: getNextAccount(),
      line: getNextAccount(),
      asset: getNextAccount(),
      mint: getNextAccount(),
      vault: getNextAccount(),
      treasury: getNextAccount(),
      dividendEvent: getNextAccount(),
      keeper: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getHarvestDividendInstructionDataDecoder().decode(instruction.data),
  };
}
